const ACTIVE_MODEL_ID = String(
  process.env.TENSORMESH_ACTIVE_MODEL_ID ||
    "7ff03808-a399-475d-ae33-c18356d74350",
);
const TOKEN_FILE = String(
  process.env.TENSORMESH_TOKEN_FILE || "/tmp/tm_token.txt",
);
const REQUEST_TIMEOUT_MS = getIntEnv(
  "TENSORMESH_REQUEST_TIMEOUT_MS",
  30000,
  1000,
);
const HTTP_RETRIES = getIntEnv("TENSORMESH_HTTP_RETRIES", 3, 0);
const POLL_INTERVAL_MS = getIntEnv("TENSORMESH_POLL_INTERVAL_MS", 10000, 1000);
const MAX_POLLS = getIntEnv("TENSORMESH_MAX_POLLS", 120, 1);
const GPU_COUNT = getIntEnv("TENSORMESH_GPU_COUNT", 2, 1);
const GPU_TYPE = String(process.env.TENSORMESH_GPU_TYPE || "GPU_TYPE_H200");
const CLOUD_PROVIDER = String(
  process.env.TENSORMESH_CLOUD_PROVIDER || "CLOUD_PROVIDER_NEBIUS",
);
const NEBIUS_REGION = String(
  process.env.TENSORMESH_NEBIUS_REGION || "NEBIUS_REGION_EU_NORTH_1",
);
const AUTOSCALING_ENABLED = getBoolEnv("TENSORMESH_AUTOSCALING_ENABLED", true);
const MIN_REPLICAS = getIntEnv("TENSORMESH_MIN_REPLICAS", 0, 0);
const MAX_REPLICAS = getIntEnv("TENSORMESH_MAX_REPLICAS", 4, 0);
const SCALE_TO_ZERO_DELAY_SECONDS = getIntEnv(
  "TENSORMESH_SCALE_TO_ZERO_DELAY_SECONDS",
  300,
  0,
);
const SCALE_DOWN_STABILIZATION_SECONDS = getIntEnv(
  "TENSORMESH_SCALE_DOWN_STABILIZATION_SECONDS",
  60,
  0,
);
const SCALE_UP_STABILIZATION_SECONDS = getIntEnv(
  "TENSORMESH_SCALE_UP_STABILIZATION_SECONDS",
  30,
  0,
);
const EXTRA_DEPLOY_BODY_JSON =
  process.env.TENSORMESH_EXTRA_DEPLOY_BODY_JSON || "";
const HUGGINGFACE_TOKEN = firstNonEmpty(
  process.env.TENSORMESH_HUGGINGFACE_TOKEN,
  process.env.HUGGINGFACE_TOKEN,
  process.env.HF_TOKEN,
  process.env.HUGGING_FACE_HUB_TOKEN,
);

if (typeof fetch !== "function") {
  console.error(
    "[FATAL] Global fetch is not available in this Node.js runtime.",
  );
  process.exit(1);
}

process.on("unhandledRejection", (error) => {
  logFatal(error);
  process.exit(1);
});

process.on("uncaughtException", (error) => {
  logFatal(error);
  process.exit(1);
});

process.on("SIGINT", () => {
  console.error("[FATAL] Interrupted.");
  process.exit(130);
});

process.on("SIGTERM", () => {
  console.error("[FATAL] Terminated.");
  process.exit(143);
});

function getIntEnv(name, fallback, minValue) {
  const raw = process.env[name];
  if (raw == null || raw === "") return fallback;
  const value = Number.parseInt(String(raw), 10);
  if (!Number.isInteger(value) || value < minValue) {
    throw new Error(`Invalid integer for ${name}: ${raw}`);
  }
  return value;
}

function getBoolEnv(name, fallback) {
  const raw = process.env[name];
  if (raw == null || raw === "") return fallback;
  const normalized = String(raw).trim().toLowerCase();
  if (["1", "true", "yes", "y", "on"].includes(normalized)) return true;
  if (["0", "false", "no", "n", "off"].includes(normalized)) return false;
  throw new Error(`Invalid boolean for ${name}: ${raw}`);
}

function firstDefined(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null) return value;
  }
  return undefined;
}

function firstNonEmpty(...values) {
  for (const value of values) {
    if (typeof value === "string" && value.trim()) return value.trim();
  }
  return null;
}

function isPlainObject(value) {
  return Object.prototype.toString.call(value) === "[object Object]";
}

function deepMerge(base, override) {
  if (!isPlainObject(base) || !isPlainObject(override)) return override;
  const merged = { ...base };
  for (const [key, value] of Object.entries(override)) {
    if (isPlainObject(value) && isPlainObject(merged[key])) {
      merged[key] = deepMerge(merged[key], value);
    } else {
      merged[key] = value;
    }
  }
  return merged;
}

function parseJsonMaybe(text) {
  if (typeof text !== "string") return null;
  const trimmed = text.trim();
  if (!trimmed) return null;
  try {
    return JSON.parse(trimmed);
  } catch {
    return null;
  }
}

function readTrimmedFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, "utf8");
    const trimmed = content.trim();
    return trimmed || null;
  } catch {
    return null;
  }
}

function getToken() {
  return firstNonEmpty(
    process.env.TENSORMESH_CONTROL_PLANE_TOKEN,
    readTrimmedFile(TOKEN_FILE),
  );
}

function requireToken() {
  const token = getToken();
  if (!token) {
    throw new Error(
      "No Tensormesh Control Plane token found in TENSORMESH_CONTROL_PLANE_TOKEN or token file.",
    );
  }
  return token;
}

function buildHeaders(token, extraHeaders) {
  const headers = {
    Authorization: `Bearer ${token}`,
    "Content-Type": "application/json",
    Accept: "application/json",
    ...extraHeaders,
  };
  return headers;
}

function buildUrl(pathname) {
  return new URL(
    pathname.replace(/^\/+/, ""),
    `${CONTROL_PLANE_BASE}/`,
  ).toString();
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function fetchWithTimeout(url, options, timeoutMs) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetch(url, { ...options, signal: controller.signal });
  } catch (error) {
    if (error && error.name === "AbortError") {
      const timeoutError = new Error(`Request timed out after ${timeoutMs}ms`);
      timeoutError.code = "ETIMEDOUT";
      throw timeoutError;
    }
    throw error;
  } finally {
    clearTimeout(timer);
  }
}

function shouldRetry(error, responseStatus) {
  if (responseStatus != null)
    return responseStatus >= 500 || responseStatus === 429;
  if (!error) return false;
  if (error.code === "ETIMEDOUT") return true;
  if (typeof error.message === "string") {
    const message = error.message.toLowerCase();
    if (
      message.includes("network") ||
      message.includes("fetch failed") ||
      message.includes("socket") ||
      message.includes("timed out")
    ) {
      return true;
    }
  }
  return false;
}

function extractErrorMessage(payload, rawText, response) {
  if (isPlainObject(payload)) {
    const candidates = [
      payload.message,
      payload.error,
      payload.detail,
      payload.reason,
      payload.error_description,
      isPlainObject(payload.error) ? payload.error.message : undefined,
      isPlainObject(payload.detail) ? payload.detail.message : undefined,
    ];
    for (const candidate of candidates) {
      if (typeof candidate === "string" && candidate.trim())
        return candidate.trim();
    }
  }
  if (typeof rawText === "string" && rawText.trim()) return rawText.trim();
  if (response) return `${response.status} ${response.statusText}`.trim();
  return "Unknown error";
}

async function requestJson(method, pathname, token, body) {
  const url = buildUrl(pathname);
  let lastError = null;
  for (let attempt = 0; attempt <= HTTP_RETRIES; attempt++) {
    try {
      const response = await fetchWithTimeout(
        url,
        {
          method,
          headers: buildHeaders(token),
          body: body === undefined ? undefined : JSON.stringify(body),
        },
        REQUEST_TIMEOUT_MS,
      );
      const rawText = await response.text();
      const payload = parseJsonMaybe(rawText);
      if (!response.ok) {
        const error = new Error(
          `HTTP ${response.status}: ${extractErrorMessage(payload, rawText, response)}`,
        );
        error.status = response.status;
        error.statusText = response.statusText;
        error.payload = payload;
        error.rawText = rawText;
        if (attempt < HTTP_RETRIES && shouldRetry(null, response.status)) {
          lastError = error;
          await sleep(Math.min(1000 * 2 ** attempt, 8000));
          continue;
        }
        throw error;
      }
      return {
        response,
        rawText,
        data: payload == null ? { raw: rawText } : payload,
      };
    } catch (error) {
      lastError = error;
      if (attempt < HTTP_RETRIES && shouldRetry(error, null)) {
        await sleep(Math.min(1000 * 2 ** attempt, 8000));
        continue;
      }
      throw error;
    }
  }
  throw lastError || new Error(`Request failed: ${method} ${url}`);
}

function normalizeEvent(event) {
  if (!isPlainObject(event)) {
    return {
      createdAt: "-",
      eventType: "UNKNOWN",
      log: String(event),
    };
  }
  return {
    createdAt: firstDefined(
      event.createdAt,
      event.created_at,
      event.timestamp,
      "-",
    ),
    eventType: firstDefined(
      event.eventType,
      event.event_type,
      event.type,
      "UNKNOWN",
    ),
    log: firstDefined(event.log, event.message, event.details, ""),
  };
}

function normalizeModel(input) {
  const model = isPlainObject(input) ? input : {};
  const rawEvents = Array.isArray(model.events)
    ? model.events
    : Array.isArray(model.history)
      ? model.history
      : Array.isArray(model.logs)
        ? model.logs
        : [];
  return {
    raw: model,
    modelId: firstDefined(model.modelId, model.model_id, model.id),
    modelName: firstDefined(model.modelName, model.model_name, model.name),
    modelPath: firstDefined(model.modelPath, model.model_path, model.path),
    endpoint: firstDefined(
      model.endpoint,
      model.apiEndpoint,
      model.api_endpoint,
      model.url,
    ),
    apiKey: firstDefined(model.apiKey, model.api_key),
    status: String(
      firstDefined(
        model.status,
        model.state,
        model.phase,
        model.deploymentStatus,
        "unknown",
      ),
    ),
    gpuType: firstDefined(model.gpuType, model.gpu_type, "-"),
    gpuCount: firstDefined(model.gpuCount, model.gpu_count, "-"),
    infra: isPlainObject(model.infra) ? model.infra : null,
    events: rawEvents.map(normalizeEvent),
  };
}

function sanitizeSingleLine(value) {
  return String(value ?? "")
    .replace(/\s+/g, " ")
    .trim();
}

function isReadyStatus(status) {
  const normalized = String(status).trim().toUpperCase();
  return (
    normalized === "MODEL_STATUS_RUNNING" ||
    normalized === "RUNNING" ||
    normalized === "READY" ||
    normalized === "ACTIVE"
  );
}

function isFailedStatus(status) {
  const normalized = String(status).trim().toUpperCase();
  return (
    normalized === "MODEL_STATUS_FAILED" ||
    normalized === "MODEL_STATUS_ERROR" ||
    normalized === "FAILED" ||
    normalized === "ERROR" ||
    normalized === "CRASHED"
  );
}

function formatEventLines(events) {
  if (!Array.isArray(events) || events.length === 0)
    return "No events available.";
  return events
    .map(
      (event) =>
        `  [${event.createdAt}] ${event.eventType}: ${sanitizeSingleLine(event.log)}`,
    )
    .join("\n");
}

function detectTrustRemoteCodeFailure(events) {
  const haystack = Array.isArray(events)
    ? events
        .map((event) => `${event.eventType} ${event.log}`)
        .join("\n")
        .toLowerCase()
    : "";
  return (
    haystack.includes("trust_remote_code") ||
    (haystack.includes("custom code") && haystack.includes("hf.co"))
  );
}

function parseExtraDeployBody() {
  if (!EXTRA_DEPLOY_BODY_JSON.trim()) return {};
  const parsed = parseJsonMaybe(EXTRA_DEPLOY_BODY_JSON);
  if (!isPlainObject(parsed)) {
    throw new Error(
      "TENSORMESH_EXTRA_DEPLOY_BODY_JSON must be a valid JSON object.",
    );
  }
  return parsed;
}

function buildDeploymentName() {
  return String(
    process.env.TENSORMESH_DEPLOYMENT_NAME || `minimax-m27-tq3-${Date.now()}`,
  );
}

function buildDeploymentBody() {
  const deploymentName = buildDeploymentName();
  const vllmCliArgs = [
    "--trust-remote-code",
    "--tensor-parallel-size",
    String(GPU_COUNT),
  ];
  let body = {
    model_name: deploymentName,
    model_path: HF_MODEL_ID,
    gpu_count: GPU_COUNT,
    gpu_type: GPU_TYPE,
    trust_remote_code: true,
    args: vllmCliArgs,
    extra_args: vllmCliArgs,
    vllm_args: vllmCliArgs,
    serving_args: vllmCliArgs,
    cli_args: vllmCliArgs,
    engine_args: {
      trust_remote_code: true,
      tensor_parallel_size: GPU_COUNT,
    },
    vllm_engine_args: {
      trust_remote_code: true,
      tensor_parallel_size: GPU_COUNT,
    },
    model_config: {
      trust_remote_code: true,
    },
    env: {
      HF_TRUST_REMOTE_CODE: "1",
      VLLM_TRUST_REMOTE_CODE: "1",
      TRUST_REMOTE_CODE: "true",
      VLLM_WORKER_MULTIPROC_METHOD: "spawn",
    },
    infra: {
      cloud_provider: CLOUD_PROVIDER,
      ...(CLOUD_PROVIDER === "CLOUD_PROVIDER_NEBIUS" && NEBIUS_REGION
        ? { nebius_region: NEBIUS_REGION }
        : {}),
    },
    autoscaling_config: {
      enabled: AUTOSCALING_ENABLED,
      min_replicas: MIN_REPLICAS,
      max_replicas: MAX_REPLICAS,
      scale_down_policy: {
        scale_to_zero_delay_seconds: SCALE_TO_ZERO_DELAY_SECONDS,
        stabilization_window_seconds: SCALE_DOWN_STABILIZATION_SECONDS,
      },
      scale_up_policy: {
        stabilization_window_seconds: SCALE_UP_STABILIZATION_SECONDS,
      },
    },
  };
  if (HUGGINGFACE_TOKEN) {
    body = deepMerge(body, {
      env: {
        HF_TOKEN: HUGGINGFACE_TOKEN,
        HUGGING_FACE_HUB_TOKEN: HUGGINGFACE_TOKEN,
        HUGGINGFACE_TOKEN: HUGGINGFACE_TOKEN,
      },
    });
  }
  const extraBody = parseExtraDeployBody();
  if (Object.keys(extraBody).length > 0) {
    body = deepMerge(body, extraBody);
  }
  return body;
}

async function getModel(modelId, token) {
  const { data } = await requestJson(
    "GET",
    `/v1/models/${encodeURIComponent(modelId)}`,
    token,
  );
  return normalizeModel(data.model || data);
}

async function pollStatus(modelId, token) {
  for (let attempt = 0; attempt < MAX_POLLS; attempt++) {
    const model = await getModel(modelId, token);
    const elapsedSeconds = Math.floor((attempt * POLL_INTERVAL_MS) / 1000);
    const lastEvent =
      model.events.length > 0 ? model.events[model.events.length - 1] : null;
    console.log(
      `[POLL ${attempt + 1}/${MAX_POLLS}] status=${model.status} gpu=${model.gpuCount}x${model.gpuType} elapsed=${elapsedSeconds}s`,
    );
    if (lastEvent && lastEvent.log) {
      console.log(`  Last event: ${sanitizeSingleLine(lastEvent.log)}`);
    }
    if (isReadyStatus(model.status)) {
      console.log("");
      console.log("[READY] Model is live.");
      console.log(`  Model ID  : ${model.modelId || modelId}`);
      console.log(`  Model name: ${model.modelName || "-"}`);
      console.log(`  HF path   : ${model.modelPath || "-"}`);
      console.log(`  Endpoint  : ${model.endpoint || "-"}`);
      console.log(`  GPU       : ${model.gpuCount}x ${model.gpuType}`);
      if (model.infra) {
        console.log(`  Infra     : ${JSON.stringify(model.infra)}`);
      }
      return model;
    }
    if (isFailedStatus(model.status)) {
      const lines = formatEventLines(model.events);
      let message = `[FAILED] Deployment failed. Status: ${model.status}\n${lines}`;
      if (detectTrustRemoteCodeFailure(model.events)) {
        message +=
          `\n[HINT] The vLLM process did not receive --trust-remote-code.` +
          ` Set TENSORMESH_EXTRA_DEPLOY_BODY_JSON to override platform-specific arg mapping.` +
          ` Example: '{"args":["--trust-remote-code","--tensor-parallel-size","${GPU_COUNT}"]}'`;
      }
      throw new Error(message);
    }
    if (attempt < MAX_POLLS - 1) {
      await sleep(POLL_INTERVAL_MS);
    }
  }
  throw new Error(
    `[TIMEOUT] Polling stopped after ${Math.floor((MAX_POLLS * POLL_INTERVAL_MS) / 1000)}s for model ${modelId}.`,
  );
}

async function deploy() {
  const token = requireToken();
  const body = buildDeploymentBody();
  console.log(`[INFO] Deploying ${HF_MODEL_ID} to Tensormesh...`);
  console.log(
    `[INFO] Deployment body args fields: args=${JSON.stringify(body.args)} extra_args=${JSON.stringify(body.extra_args)} vllm_args=${JSON.stringify(body.vllm_args)}`,
  );
  const { data } = await requestJson("POST", "/v1/models", token, body);
  const model = normalizeModel(data.model || data);
  const modelId = model.modelId;
  if (!modelId) {
    const responseDump = JSON.stringify(data, null, 2);
    throw new Error(
      `Deployment response did not include a model ID.\n${responseDump}`,
    );
  }
  console.log(`[SUCCESS] Deployment created. modelId=${modelId}`);
  console.log("[INFO] Polling status...");
  await pollStatus(modelId, token);
}

async function checkActive(modelId) {
  const token = requireToken();
  if (!modelId) {
    throw new Error("No active model ID provided.");
  }
  console.log(`[INFO] Checking deployment: ${modelId}`);
  await pollStatus(modelId, token);
}

function logFatal(error) {
  if (!error) {
    console.error("[FATAL] Unknown error");
    return;
  }
  const message =
    typeof error.message === "string" && error.message.trim()
      ? error.message
      : String(error);
  console.error(`[FATAL] ${message}`);
  if (error.status) {
    console.error(
      `HTTP Status: ${error.status}${error.statusText ? ` ${error.statusText}` : ""}`,
    );
  }
  if (error.payload) {
    try {
      console.error(JSON.stringify(error.payload, null, 2));
      return;
    } catch {}
  }
  if (typeof error.rawText === "string" && error.rawText.trim()) {
    console.error(error.rawText);
  }
}

async function main() {
  const mode = String(process.argv[2] || "deploy")
    .trim()
    .toLowerCase();
  if (mode === "status") {
    const modelId = firstNonEmpty(process.argv[3], ACTIVE_MODEL_ID);
    await checkActive(modelId);
    return;
  }
  if (mode === "deploy") {
    await deploy();
    return;
  }
  throw new Error(`Unknown mode: ${mode}. Use "deploy" or "status".`);
}

main().catch((error) => {
  logFatal(error);
  process.exit(1);
});
